// ---------- 未装载货物的更正 ----------

func TestAmendUnloadedCargoSuccess(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCargo("  G1  ", 20, "  Shanghai  ", true); err != nil {
		t.Fatal(err)
	}
	if err := r.AmendCargo(" G1 ", 35, "  Beijing ", false); err != nil {
		t.Fatal(err)
	}
	cv, err := r.Cargo("G1")
