271	
272		se := submitExpectReject(t, r, "adj-wm", []Op{
273			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
274			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
275		})
276		if se.Kind != ErrOverweight {
277			t.Fatalf("同舱超重与混装并存时应先报重量，实际 Kind=%s", se.Kind)
278		}
279		// 错误对象编号是该舱位，而不是任何一件货物。
280		if se.ID != "C1" {
