296	// 预计合计溢出 int64 的舱位同时存在混装冲突时，仍先报告重量（溢出）原因，
297	// 对象为该舱位而非货物。
298	func TestAdjustOverflowReportedBeforeMixed(t *testing.T) {
299		r := NewRegistry()
300		mustRegisterCompartment(t, r, "C1", math.MaxInt64)
301		mustRegisterCargo(t, r, "G1", math.MaxInt64, "上海", false)
302		mustRegisterCargo(t, r, "G2", math.MaxInt64, "北京", true)
