305		se := submitExpectReject(t, r, "adj-ov", []Op{
306			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
307		})
308		if se.Kind != ErrOverflow {
309			t.Fatalf("溢出与混装并存时应先报溢出，实际 Kind=%s", se.Kind)
310		}
311		if se.ID != "C1" {
312			t.Fatalf("溢出原因应指向舱位 C1，实际 %q", se.ID)
313		}
314		if se.AdjustmentID != "adj-ov" {
315			t.Fatalf("错误应携带编号 adj-ov，实际 %q", se.AdjustmentID)
316		}
317		// 拒绝后 G2 仍未装载，C1 仍只有 G1。
318		g2, _ := r.Cargo("G2")
319		if g2.Loaded || g2.CompartmentID != "" {
320			t.Fatalf("G2 应仍未装载: %+v", g2)
321		}
322		c1, _ := r.Compartment("C1")
323		if !reflect.DeepEqual(cargoIDs(*c1), []string{"G1"}) {
324			t.Fatalf("C1 应仍只有 G1: %+v", c1.Cargo)
325		}
326	}
327	
328	// ---------- 混装冲突的对象选择 ----------
329	
330	// 重量合法、只有混装冲突时，错误对象是不允许混装的货物中编号字典序
331	// 最靠前的一件（含原舱货物），而不是最后加入舱内的那件。
332	func TestAdjustMixedConflictOffenderMayPrecedeIncomingCargo(t *testing.T) {
333		r := NewRegistry()
334		mustRegisterCompartment(t, r, "C1", 1000)
335		mustRegisterCargo(t, r, "G2", 10, "上海", false) // 原舱，禁混
336		mustRegisterCargo(t, r, "G7", 10, "上海", false) // 原舱，禁混
337		mustRegisterCargo(t, r, "G1", 10, "北京", true)  // 未装载，许混，本批加入
338		mustAdjust(t, r, "init", []Op{
339			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
340			{Kind: OpLoad, CargoID: "G7", Target: "C1"},
341		})
342	
343		compBefore := snapshotCompartments(r, "C1")
344		cargoBefore := snapshotCargo(r, "G1", "G2", "G7")
345	
346		// 最终 C1 = {G2, G7}(上海,禁混) + G1(北京,许混)，重量 30 合法，
347		// 只有混装冲突。违规货物集合是原舱的 {G2, G7}，字典序最靠前为 G2；
348		// 最后加入的 G1 允许混装，根本不在违规集合内。
349		se := submitExpectReject(t, r, "adj-m2", []Op{
350			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
351		})
352		if se.Kind != ErrMixedLoading || se.ID != "G2" {
353			t.Fatalf("应指出原舱内字典序最靠前的违规货物 G2，实际 Kind=%s ID=%q", se.Kind, se.ID)
354		}
355		if !strings.Contains(se.Error(), "C1") {
356			t.Fatalf("说明应指出冲突舱位 C1: %s", se.Error())
357		}
358		if se.AdjustmentID != "adj-m2" {
359			t.Fatalf("错误应携带调整编号 adj-m2，实际 %q", se.AdjustmentID)
360		}
361	
362		// 拒绝后回查：G2、G7 仍在 C1，G1 仍未装载；重量、目的地、混装许可、
363		// 舱位清单、已用与剩余重量都与提交前一致。
364		assertCompartmentsUnchanged(t, r, compBefore)
365		assertCargoUnchanged(t, r, cargoBefore)
366	}
367	
368	// 违规货物既包括原舱货物也包括本批移入货物时，仍按全部违规货物编号的
369	// 字典序取最靠前的一件，与谁最后进舱无关。
370	func TestAdjustMixedConflictOffenderAcrossStayingAndIncoming(t *testing.T) {
371		r := NewRegistry()
372		mustRegisterCompartment(t, r, "C1", 1000)
373		mustRegisterCompartment(t, r, "C2", 1000)
374		// C1 原舱：G5（上海，禁混）。C2：G0（广州，禁混）。未装载：
375		// G9（北京，许混）。初始各舱均同目的地，初始装载本身合法。
376		mustRegisterCargo(t, r, "G5", 10, "上海", false)
377		mustRegisterCargo(t, r, "G0", 10, "广州", false)
378		mustRegisterCargo(t, r, "G9", 10, "北京", true)
379		mustAdjust(t, r, "init", []Op{
380			{Kind: OpLoad, CargoID: "G5", Target: "C1"},
381			{Kind: OpLoad, CargoID: "G0", Target: "C2"},
382		})
383	
384		compBefore := snapshotCompartments(r, "C1", "C2")
385		cargoBefore := snapshotCargo(r, "G0", "G5", "G9")
386	
387		// 把 G0 移入 C1、把 G9 装入 C1：最终 C1 = G5(上海,禁混)、
388		// G0(广州,禁混)、G9(北京,许混)，重量 30 合法，只有混装冲突。
389		// 违规集合 {G0(本批移入), G5(原舱)}，字典序最靠前为 G0。
390		se := submitExpectReject(t, r, "adj-m3", []Op{
391			{Kind: OpMove, CargoID: "G0", Target: "C1"},
392			{Kind: OpLoad, CargoID: "G9", Target: "C1"},
393		})
394		if se.Kind != ErrMixedLoading || se.ID != "G0" {
395			t.Fatalf("应指出全部违规货物中编号最靠前的 G0，实际 Kind=%s ID=%q", se.Kind, se.ID)
396		}
397		if !strings.Contains(se.Error(), "C1") {
398			t.Fatalf("说明应指出冲突舱位 C1: %s", se.Error())
399		}
400		assertCompartmentsUnchanged(t, r, compBefore)
401		assertCargoUnchanged(t, r, cargoBefore)
402	}
403	
404	// ---------- 拒绝后仍可查询到原配载（整批原子性）----------
405	
406	// 清单里包含一项本来能够成功的卸下或移动时，不能留下那一项已生效的
407	// 状态；同批另一项操作导致整批被拒后，全部状态与提交前一致。
408	func TestAdjustRejectionAtomicAcrossUnloadAndMove(t *testing.T) {
409		// 形态一：本可成功的卸下 + 引发超重的移动。报告 C2 超重，但卸下不生效。
410		r := NewRegistry()
411		mustRegisterCompartment(t, r, "C1", 100)
412		mustRegisterCompartment(t, r, "C2", 100)
413		mustRegisterCargo(t, r, "GU", 40, "X", true) // 将被卸下（单独看合法）
414		mustRegisterCargo(t, r, "GM", 60, "X", true) // 将被移动到 C2
415		mustRegisterCargo(t, r, "GX", 90, "X", true) // 留在 C2
416		mustAdjust(t, r, "init", []Op{
417			{Kind: OpLoad, CargoID: "GU", Target: "C1"},
418			{Kind: OpLoad, CargoID: "GM", Target: "C1"},
419			{Kind: OpLoad, CargoID: "GX", Target: "C2"},
420		})
421	
422		compBefore := snapshotCompartments(r, "C1", "C2")
423		cargoBefore := snapshotCargo(r, "GU", "GM", "GX")
424	
425		se := submitExpectReject(t, r, "adj-atomic1", []Op{
426			{Kind: OpUnload, CargoID: "GU"},             // 本可成功：C1 40 -> 0
427			{Kind: OpMove, CargoID: "GM", Target: "C2"}, // C2: 90+60=150 超重
428		})
429		if se.Kind != ErrOverweight || se.ID != "C2" {
430			t.Fatalf("应报告 C2 超重，实际 Kind=%s ID=%q", se.Kind, se.ID)
431		}
432		if !strings.Contains(se.Error(), "150") || !strings.Contains(se.Error(), "100") {
433			t.Fatalf("超重说明应含预计总重 150 与承重 100: %s", se.Error())
434		}
435		assertCompartmentsUnchanged(t, r, compBefore)
436		assertCargoUnchanged(t, r, cargoBefore)
437	
438		// 形态二：本可成功的移动 + 引发混装冲突的装载。报告 C1 混装，但移动
439		// 不生效。C1 原舱为 GM（北京，许混），把另一舱的 GS（同为北京、许混）
440		// 移入 C1 本身合法；同批把未装载的 GN（深圳，禁混）装入 C1 才造成冲突。
441		r2 := NewRegistry()
442		mustRegisterCompartment(t, r2, "C1", 1000)
443		mustRegisterCompartment(t, r2, "C2", 1000)
444		mustRegisterCargo(t, r2, "GM", 10, "北京", true)
445		mustRegisterCargo(t, r2, "GS", 10, "北京", true)
446		mustRegisterCargo(t, r2, "GN", 10, "深圳", false)
447		mustAdjust(t, r2, "init", []Op{
448			{Kind: OpLoad, CargoID: "GM", Target: "C1"},
449			{Kind: OpLoad, CargoID: "GS", Target: "C2"},
450		})
451	
452		compBefore2 := snapshotCompartments(r2, "C1", "C2")
453		cargoBefore2 := snapshotCargo(r2, "GM", "GS", "GN")
454	
455		se2 := submitExpectReject(t, r2, "adj-atomic2", []Op{
456			{Kind: OpMove, CargoID: "GS", Target: "C1"}, // 本可成功：同目的地共舱
457			{Kind: OpLoad, CargoID: "GN", Target: "C1"}, // 深圳 vs 北京，GN 禁混
458		})
459		if se2.Kind != ErrMixedLoading || se2.ID != "GN" {
460			t.Fatalf("应报告 C1 混装冲突并指出 GN，实际 Kind=%s ID=%q", se2.Kind, se2.ID)
461		}
462		if !strings.Contains(se2.Error(), "C1") {
463			t.Fatalf("说明应指出冲突舱位 C1: %s", se2.Error())
464		}
465		assertCompartmentsUnchanged(t, r2, compBefore2)
466		assertCargoUnchanged(t, r2, cargoBefore2)
467	}
468	
469	// 被拒绝后，原本已装载货物仍在原舱位、原本未装载货物仍未装载；失败不
470	// 占用编号，用同一编号提交修正后的合法安排可以成功，随后回查到的是新
471	// 配载，而被拒当刻回查到的是原配载。
472	func TestAdjustRejectionLeavesOriginalStowageQueryable(t *testing.T) {
473		r := NewRegistry()
474		mustRegisterCompartment(t, r, "C1", 100)
475		mustRegisterCompartment(t, r, "C2", 100)
476		mustRegisterCargo(t, r, "G1", 60, "X", true)
477		mustRegisterCargo(t, r, "G2", 50, "X", true)
478		mustRegisterCargo(t, r, "G3", 10, "X", true)
479		mustAdjust(t, r, "a0", []Op{
480			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
481			{Kind: OpLoad, CargoID: "G2", Target: "C2"},
482			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
483		})
484	
485		compBefore := snapshotCompartments(r, "C1", "C2")
486		cargoBefore := snapshotCargo(r, "G1", "G2", "G3")
487	
488		// 卸下 G3 本可成功；移动 G1 到 C2 导致 C2 超重（50+60>100），整批拒绝。
489		se := submitExpectReject(t, r, "  bad-batch  ", []Op{
490			{Kind: OpUnload, CargoID: "G3"},
491			{Kind: OpMove, CargoID: "G1", Target: "C2"},
492		})
493		if se.Kind != ErrOverweight || se.ID != "C2" {
494			t.Fatalf("应报告 C2 超重，实际 Kind=%s ID=%q", se.Kind, se.ID)
495		}
496		if se.AdjustmentID != "bad-batch" {
497			t.Fatalf("错误应携带去空白后的编号 bad-batch，实际 %q", se.AdjustmentID)
498		}
499		// 被拒当刻即可查询到原配载。
500		assertCompartmentsUnchanged(t, r, compBefore)
501		assertCargoUnchanged(t, r, cargoBefore)
502	
503		// 失败不占用编号：同一编号用于修正后的合法内容应成功。
504		res, err := r.Adjust("bad-batch", []Op{{Kind: OpUnload, CargoID: "G3"}})
505		if err != nil {
506			t.Fatalf("失败不应占用编号，修正后应成功: %v", err)
507		}
508		if res == nil || len(res.CargoChanges) != 1 ||
509			res.CargoChanges[0].CargoID != "G3" || res.CargoChanges[0].From != "C1" ||
510			res.CargoChanges[0].To != "" {
511			t.Fatalf("修正后调整结果异常: %+v", res)
512		}
513		g3, _ := r.Cargo("G3")
514		if g3.Loaded || g3.CompartmentID != "" {
515			t.Fatalf("G3 应已卸下: %+v", g3)
516		}
517		// 同批被拒涉及的 G1、G2 归属保持初始终态。
518		g1, _ := r.Cargo("G1")
519		g2, _ := r.Cargo("G2")
520		if g1.CompartmentID != "C1" || g2.CompartmentID != "C2" {
521			t.Fatalf("G1、G2 归属不应改变: %+v %+v", g1, g2)
522		}
523	}
524	
525	// ---------- 两种入口各自的用途 ----------
526	
527	// Preview 列出全部拒绝原因，正式提交只返回一个结构化错误；两者对首个
528	// 原因的判定一致，而 Preview 额外保留其余原因与受影响舱位的前后清单。
529	func TestPreviewListsAllReasonsAdjustReturnsOne(t *testing.T) {
530		r := NewRegistry()
531		mustRegisterCompartment(t, r, "C1", 50)
532		mustRegisterCompartment(t, r, "C2", 50)
533		// C1：上海(禁混)+北京(允许) 合计 80 > 50，超重且混装；C2：仅超重。
534		mustRegisterCargo(t, r, "G1", 40, "上海", false)
535		mustRegisterCargo(t, r, "G2", 40, "北京", true)
536		mustRegisterCargo(t, r, "G3", 30, "X", true)
537		mustRegisterCargo(t, r, "G4", 30, "X", true)
538		ops := []Op{
539			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
540			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
541			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
542			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
543		}
544	
545		pv, err := r.Preview(ops)
546		if err != nil {
547			t.Fatal(err)
548		}
549		if pv.Submittable {
550			t.Fatal("预览应判定不可提交")
551		}
552		got := make([][2]string, 0, len(pv.Rejections))
553		for _, x := range pv.Rejections {
554			got = append(got, [2]string{x.CompartmentID, x.Kind.String()})
555		}
556		want := [][2]string{
557			{"C1", "超重"},
558			{"C1", "混装冲突"},
559			{"C2", "超重"},
560		}
561		if !reflect.DeepEqual(got, want) {
562			t.Fatalf("Preview 应列全全部拒绝原因: %+v", got)
563		}
564		// Preview 给出全部受影响舱位的完整前后清单，这是 Adjust 的单条错误
565		// 不提供的信息。
566		if len(pv.Compartments) != 2 ||
567			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
568			t.Fatalf("Preview 应列出两个受影响舱位: %+v", pv.Compartments)
569		}
570		assertAllEmpty(t, r)
571	
572		// 正式提交只返回一个结构化错误，首个原因与预览第一条一致。
573		se := submitExpectReject(t, r, "p-1", ops)
574		if se.Kind != ErrOverweight || se.ID != "C1" {
575			t.Fatalf("Adjust 应只报首个原因 C1 超重，实际 Kind=%s ID=%q", se.Kind, se.ID)
576		}
577		if se.AdjustmentID != "p-1" {
578			t.Fatalf("Adjust 错误应携带编号 p-1，实际 %q", se.AdjustmentID)
579		}
580		// *Error 只承载单条原因；调用方需要全部原因时应使用 Preview。
581		// 提交被拒后原配载仍可回查，且该编号未被占用。
582		assertAllEmpty(t, r)
583		if _, err := r.Adjust("p-1", []Op{{Kind: OpLoad, CargoID: "G3", Target: "C2"}}); err != nil {
584			t.Fatalf("被拒编号不应被占用: %v", err)
585		}
586	}
587	
588	// Preview 判为可提交的安排，用同一批操作正式提交应成功，提交后查询结果
589	// 与预计配载对应——保留两种入口在成功路径上的配合。
590	func TestPreviewSubmittableThenAdjustSucceeds(t *testing.T) {
591		r := NewRegistry()
592		mustRegisterCompartment(t, r, "C1", 30)
593		mustRegisterCompartment(t, r, "C2", 30)
594		mustRegisterCargo(t, r, "G1", 30, "上海", false)
595		mustRegisterCargo(t, r, "G2", 30, "上海", false)
596		mustAdjust(t, r, "init", []Op{
597			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
598			{Kind: OpLoad, CargoID: "G2", Target: "C2"},
599		})
600		ops := []Op{
601			{Kind: OpMove, CargoID: "G1", Target: "C2"},
602			{Kind: OpMove, CargoID: "G2", Target: "C1"},
603		}
604		pv, err := r.Preview(ops)
605		if err != nil {
606			t.Fatal(err)
607		}
608		if !pv.Submittable || len(pv.Rejections) != 0 {
609			t.Fatalf("满载互换应可提交: %+v", pv.Rejections)
610		}
611		res, err := r.Adjust("swap-1", ops)
612		if err != nil {
613			t.Fatalf("预览可提交的安排正式提交应成功: %v", err)
614		}
615		if res == nil || res.ID != "swap-1" {
616			t.Fatalf("成功结果异常: %+v", res)
617		}
618		g1, _ := r.Cargo("G1")
619		g2, _ := r.Cargo("G2")
620		if g1.CompartmentID != "C2" || g2.CompartmentID != "C1" {
621			t.Fatalf("提交后配载应与预览一致: G1=%s G2=%s", g1.CompartmentID, g2.CompartmentID)
622		}
623	}
624	
625	// ---------- 合法配载不得被误伤 ----------
626	
627	// 同一目的地货物共舱、总重量恰好达到承重的批处理应正常成功并返回完整
628	// 变化结果，避免把合法配载也挡住。
629	func TestAdjustSameDestinationExactCapacitySucceeds(t *testing.T) {
630		r := NewRegistry()
631		mustRegisterCompartment(t, r, "C1", 100)
632		mustRegisterCompartment(t, r, "C2", 50)
633		mustRegisterCargo(t, r, "G1", 60, "上海", false)
634		mustRegisterCargo(t, r, "G2", 40, "上海", false) // C1 恰好 100，同目的地可共舱
635		mustRegisterCargo(t, r, "G3", 50, "北京", true)  // C2 恰好 50
636	
637		res, err := r.Adjust(" ok-2 ", []Op{
638			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
639			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
640			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
641		})
642		if err != nil {
643			t.Fatalf("同目的地共舱且恰好满载应成功: %v", err)
644		}
645		if res == nil || res.ID != "ok-2" {
646			t.Fatalf("成功结果应携带去空白后的编号 ok-2: %+v", res)
647		}
648		if len(res.CargoChanges) != 3 || len(res.CompartmentChanges) != 2 {
649			t.Fatalf("应返回三件货物与两个舱位的变化: %+v", res)
650		}
651		c1, _ := r.Compartment("C1")
652		if c1.UsedWeight != 100 || c1.RemainingWeight != 0 ||
653			!reflect.DeepEqual(cargoIDs(*c1), []string{"G1", "G2"}) {
654			t.Fatalf("C1 应恰好满载且清单为 G1、G2: %+v", c1)
655		}
656		c2, _ := r.Compartment("C2")
657		if c2.UsedWeight != 50 || c2.RemainingWeight != 0 ||
658			!reflect.DeepEqual(cargoIDs(*c2), []string{"G3"}) {
659			t.Fatalf("C2 应恰好满载且清单为 G3: %+v", c2)
660		}
661		// 货物登记资料保持原样。
662		g1, _ := r.Cargo("G1")
663		if g1.Weight != 60 || g1.Destination != "上海" || g1.AllowMixed {
664			t.Fatalf("G1 资料不应改变: %+v", g1)
665		}
666	}
